package oracle;
import java.io.*;import java.util.*;import org.json.simple.*;import org.json.simple.parser.JSONParser;
import core.game.node.entity.Entity;import core.game.node.entity.player.Player;import core.game.node.entity.impl.WalkingQueue;import core.game.world.map.*;import core.game.node.item.GroundItem;
public class Support {
 public static Entity entity;static WalkingQueue queue;static Map input;static List<Object> events;static Map<String,Integer> calls;static Map<String,Location> locations;static List<Point> views;static int nextItem;
 public static class Failure extends RuntimeException{}
 static int n(Object v){return ((Number)v).intValue();}static int v(Map m,String k,int d){return m.get(k)==null?d:n(m.get(k));}static boolean b(Map m,String k){return Boolean.TRUE.equals(m.get(k));}
 static double d(Object v){if(v instanceof Number)return ((Number)v).doubleValue();return Double.parseDouble((String)v);}
 public static String bits(double v){return Long.toHexString(Double.doubleToLongBits(v));}
 public static Object coord(Location l){return l==null?null:Arrays.asList(l.getX(),l.getY(),l.getZ());}
 static Location loc(Object v){if(v==null)return null;if(v instanceof String)return locations.get(v);List a=(List)v;return Location.create(n(a.get(0)),n(a.get(1)),n(a.get(2)));}
 public static void emit(String name,Object...args){List<Object> row=new ArrayList<>();row.add(name);Collections.addAll(row,args);events.add(row);int call=calls.merge(name,1,Integer::sum);for(Object h:(List)input.getOrDefault("hooks",Collections.emptyList())){Map hook=(Map)h;if(name.equals(hook.get("event"))&&call==v(hook,"at",1))for(Object a:(List)hook.get("actions"))act((Map)a);}}
 public static boolean timer(String name){emit("timer",name);return b(input,name);}
 public static boolean marathon(){emit("marathon");return b(input,"marathon");}
 public static boolean zone(Location from,Location to){emit("zone",coord(from),coord(to));List a=(List)input.getOrDefault("zoneAnswers",Collections.emptyList());int i=calls.get("zone")-1;return i>=a.size()||Boolean.TRUE.equals(a.get(i));}
 public static void region(Location from,Location to){emit("region",coord(from),coord(to));}
 public static GroundItem create(Location location){GroundItem item=new GroundItem(nextItem++,location);emit("create",item.token,coord(location));return item;}
 static void set(Map a){if(a.containsKey("location"))entity.location=loc(a.get("location"));if(a.containsKey("teleport"))entity.props.teleport=loc(a.get("teleport"));if(a.containsKey("last"))entity.flags.last=loc(a.get("last"));if(a.containsKey("foot"))queue.setFootPrint(loc(a.get("foot")));if(a.containsKey("scene"))entity.flags.update=b(a,"scene");if(a.containsKey("teleporting"))entity.props.teleporting=b(a,"teleporting");if(a.containsKey("running"))queue.setRunning(b(a,"running"));if(a.containsKey("disabled"))queue.setRunDisabled(b(a,"disabled"));if(a.containsKey("toggled"))entity.settings.toggled=b(a,"toggled");if(a.containsKey("energy"))entity.settings.energy=d(a.get("energy"));if(a.containsKey("weight"))entity.settings.weight=d(a.get("weight"));if(a.containsKey("agility"))entity.agility=v(a,"agility",1);if(a.containsKey("incrementer"))entity.incrementer=v(a,"incrementer",0);if(a.containsKey("draw"))entity.draw=b(a,"draw");}
 static Object act(Map a){String op=(String)a.get("op");switch(op){
 case "set":set(a);break;case "reset":if(a.containsKey("running"))queue.reset(b(a,"running"));else queue.reset();break;
 case "add":if(a.containsKey("disabled"))queue.addPath(v(a,"x",0),v(a,"y",0),b(a,"disabled"));else queue.addPath(v(a,"x",0),v(a,"y",0));break;
 case "point":queue.addPoint(v(a,"x",0),v(a,"y",0),b(a,"disabled"));break;case "seed":queue.getQueue().add(new Point(v(a,"x",0),v(a,"y",0)));break;
 case "retain":views.add(new ArrayList<Point>(queue.getQueue()).get(v(a,"index",0)));break;case "mutatePoint":views.get(v(a,"index",0)).setRunDisabled(b(a,"disabled"));break;
 case "clear":queue.getQueue().clear();break;case "update":queue.update();break;case "teleport":return queue.updateTeleport();
 case "region":return queue.updateRegion(loc(a.get("from")),loc(a.get("to")),b(a,"move"));case "energy":queue.updateRunEnergy(b(a,"decrease"));break;case "back":queue.walkBack();break;
 case "routeNull":queue.routeItems.add(null);break;case "routeClear":queue.routeItems.clear();break;case "routeReplace":queue.routeItems=new ArrayList<>();break;
 case "mutateLocation":{Location l=loc(a.get("which"));l.setX(v(a,"x",0));l.setY(v(a,"y",0));l.setZ(v(a,"z",0));break;}
 case "fail":throw new Failure();default:throw new IllegalArgumentException(op);
 }return null;}
 static Object point(Point p){return Arrays.asList(p.getX(),p.getY(),p.getDirection()==null?null:p.getDirection().ordinal(),p.getDiffX(),p.getDiffY(),p.isRunDisabled());}
 static Object snapshot(Object result,String error){Map<String,Object> out=new TreeMap<>();List<Object> ps=new ArrayList<>();for(Point p:queue.getQueue())ps.add(point(p));out.put("points",ps);List<Object> vs=new ArrayList<>();for(Point p:views)vs.add(point(p));out.put("views",vs);List<Object> routes=new ArrayList<>();for(GroundItem item:queue.routeItems)routes.add(item==null?null:Arrays.asList(item.token,coord(item.location)));out.put("routes",routes);
 out.put("location",coord(entity.location));out.put("foot",coord(queue.getFootPrint()));out.put("last",coord(entity.flags.last));out.put("teleport",coord(entity.props.teleport));out.put("scene",entity.flags.update);out.put("teleporting",entity.props.teleporting);out.put("direction",entity.direction==null?null:entity.direction.ordinal());out.put("walk",queue.getWalkDir());out.put("run",queue.getRunDir());out.put("running",queue.isRunning());out.put("disabled",queue.isRunDisabled());out.put("runningBoth",queue.isRunningBoth());out.put("moving",queue.isMoving());out.put("hasPath",queue.hasPath());out.put("energy",bits(entity.settings.energy));out.put("weight",bits(entity.settings.weight));out.put("toggled",entity.settings.toggled);out.put("agility",entity.agility);out.put("incrementer",entity.incrementer);out.put("draw",entity.draw);
 List<Location> ls=new ArrayList<>(Arrays.asList(entity.location,queue.getFootPrint(),entity.flags.last,entity.props.teleport));ls.addAll(locations.values());List<Object> coords=new ArrayList<>();List<Object> aliases=new ArrayList<>();for(Location l:ls){coords.add(coord(l));List<Boolean> row=new ArrayList<>();for(Location r:ls)row.add(l!=null&&l==r);aliases.add(row);}out.put("locations",coords);out.put("aliases",aliases);out.put("events",new ArrayList<>(events));out.put("result",result);out.put("error",error);return out;}
 public static void main(String[] args)throws Exception{try(BufferedReader r=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){input=(Map)new JSONParser().parse(line);events=new ArrayList<>();calls=new HashMap<>();locations=new TreeMap<>();views=new ArrayList<>();nextItem=1;Map defs=(Map)input.getOrDefault("locations",Collections.emptyMap());for(Object k:defs.keySet())locations.put((String)k,loc(defs.get(k)));entity=Boolean.FALSE.equals(input.get("player"))?new Entity():new Player();entity.location=loc(input.getOrDefault("location",Arrays.asList(3207L,3216L,0L)));queue=new WalkingQueue(entity);entity.queue=queue;set((Map)input.getOrDefault("fields",Collections.emptyMap()));List<Object> states=new ArrayList<>();for(Object a:(List)input.get("actions")){events.clear();Object result=null;String error=null;try{result=act((Map)a);}catch(Failure ex){error="Binding";}catch(NullPointerException ex){error="Null";}catch(ClassCastException ex){error="Type";}catch(ConcurrentModificationException ex){error="ConcurrentModification";}states.add(snapshot(result,error));}input.put("expected",states);System.out.println(JSONValue.toJSONString(input));}}}
}
